import pandas as pd

employees = pd.DataFrame({
    "emp_id": [1, 2, 3, 4],
    "name": ["Alice", "Bob", "Charlie", "Diana"],
})

salaries = pd.DataFrame({
    "emp_id": [1, 2, 3, 5],
    "salary": [70000, 65000, 80000, 90000],
})

merged = pd.merge(employees, salaries, on="emp_id", how="inner")
print(merged)

import pandas as pd

q1 = pd.DataFrame({
    "product": ["Widget", "Gadget", "Doohickey"],
    "units_sold": [120, 85, 40],
})
q2 = pd.DataFrame({
    "product": ["Widget", "Gadget", "Doohickey"],
    "units_sold": [135, 90, 55],
})
q3 = pd.DataFrame({
    "product": ["Widget", "Gadget", "Doohickey"],
    "units_sold": [150, 70, 60],
})

annual = pd.concat([q1, q2, q3], ignore_index=True)
print(annual)
